"use client";

import type { ComponentProps } from "react";

import { cn } from "@/lib/utils";
import { CustomButton } from "@/registry/new-york/custom-button/CustomButton";
import { socialLoginProviders } from "@/registry/new-york/social-login-button/social-login-providers";
import type * as ProviderTypes from "@/registry/new-york/social-login-button/social-login-providers";

export type SocialLoginProvider = ProviderTypes.SocialLoginProvider;

export interface SocialLoginButtonProps extends Omit<
  ComponentProps<"button">,
  "children"
> {
  provider: SocialLoginProvider;
  /** Defaults to “Continue with {provider}”. */
  label?: string;
  variant?: "outline" | "brand";
  size?: "sm" | "md" | "lg";
  iconOnly?: boolean;
  loading?: boolean;
}

const sizes = {
  lg: "h-12 px-5 text-base",
  md: "h-11 px-4 text-sm",
  sm: "h-9 px-3 text-sm",
};
const iconSizes = { lg: "w-12", md: "w-11", sm: "w-9" };

export const SocialLoginButton = ({
  provider,
  label,
  variant = "outline",
  size = "md",
  iconOnly = false,
  loading = false,
  disabled,
  className,
  ...props
}: SocialLoginButtonProps) => {
  const { icon: Icon, name, brandClassName } = socialLoginProviders[provider];
  const text = label ?? `Continue with ${name}`;

  return (
    <CustomButton
      type="button"
      {...props}
      variant="unstyled"
      size={size}
      loading={loading}
      icon={iconOnly ? Icon : undefined}
      leftIcon={iconOnly ? undefined : Icon}
      iconSize={20}
      aria-label={props["aria-label"] ?? (iconOnly ? text : undefined)}
      data-slot="social-login-button"
      data-provider={provider}
      aria-busy={loading || undefined}
      disabled={disabled}
      className={cn(
        "focus-visible:ring-ring focus-visible:ring-offset-background min-w-0 gap-3 rounded-lg border leading-none shadow-none transition-[background-color,color,border-color,transform] duration-150 focus-visible:ring-2 focus-visible:ring-offset-2 enabled:active:scale-[0.98] disabled:pointer-events-auto disabled:cursor-not-allowed motion-reduce:transform-none motion-reduce:transition-none [&_svg]:size-5 motion-reduce:[&_svg]:animate-none",
        sizes[size],
        variant === "outline"
          ? "border-input bg-background text-foreground enabled:hover:bg-accent"
          : brandClassName,
        iconOnly &&
          cn(
            iconSizes[size],
            "max-h-none min-h-0 max-w-none min-w-0 shrink-0 px-0"
          ),
        className
      )}
    >
      {iconOnly ? undefined : text}
    </CustomButton>
  );
};

import SiApple from "@icons-pack/react-simple-icons/icons/SiApple";
import SiDiscord from "@icons-pack/react-simple-icons/icons/SiDiscord";
import SiFacebook from "@icons-pack/react-simple-icons/icons/SiFacebook";
import SiGithub from "@icons-pack/react-simple-icons/icons/SiGithub";
import SiGitlab from "@icons-pack/react-simple-icons/icons/SiGitlab";
import SiSpotify from "@icons-pack/react-simple-icons/icons/SiSpotify";
import SiTwitch from "@icons-pack/react-simple-icons/icons/SiTwitch";
import SiX from "@icons-pack/react-simple-icons/icons/SiX";

import {
  GoogleLogo,
  LinkedInLogo,
  MicrosoftLogo,
  SlackLogo,
} from "@/registry/new-york/social-login-button/SocialLoginBrandIcons";

const surface =
  "border-input bg-background text-foreground enabled:hover:bg-accent";
const monochrome =
  "border-transparent bg-zinc-950 text-white enabled:hover:bg-zinc-800 dark:bg-white dark:text-zinc-950 dark:enabled:hover:bg-zinc-200";

export const socialLoginProviders = {
  apple: { brandClassName: monochrome, icon: SiApple, name: "Apple" },
  discord: {
    brandClassName:
      "border-transparent bg-[#5865f2] text-white enabled:hover:bg-[#4752c4]",
    icon: SiDiscord,
    name: "Discord",
  },
  facebook: {
    brandClassName:
      "border-transparent bg-[#0866ff] text-white enabled:hover:bg-[#0758dc]",
    icon: SiFacebook,
    name: "Facebook",
  },
  github: { brandClassName: monochrome, icon: SiGithub, name: "GitHub" },
  gitlab: { brandClassName: surface, icon: SiGitlab, name: "GitLab" },
  google: { brandClassName: surface, icon: GoogleLogo, name: "Google" },
  linkedin: {
    brandClassName:
      "border-transparent bg-[#0a66c2] text-white enabled:hover:bg-[#004182]",
    icon: LinkedInLogo,
    name: "LinkedIn",
  },
  microsoft: {
    brandClassName: surface,
    icon: MicrosoftLogo,
    name: "Microsoft",
  },
  slack: { brandClassName: surface, icon: SlackLogo, name: "Slack" },
  spotify: {
    brandClassName:
      "border-transparent bg-[#1ed760] text-black enabled:hover:bg-[#1bc457]",
    icon: SiSpotify,
    name: "Spotify",
  },
  twitch: {
    brandClassName:
      "border-transparent bg-[#9146ff] text-white enabled:hover:bg-[#772ce8]",
    icon: SiTwitch,
    name: "Twitch",
  },
  x: { brandClassName: monochrome, icon: SiX, name: "X" },
};

export type SocialLoginProvider = keyof typeof socialLoginProviders;

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
